=<div style="font-family: Arial, Helvetica, sans-serif; max-width:760px; margin:0 auto; color:#000; line-height:1.6;">

  <!-- ===== STATIC TOP HEADING ===== -->
  <div style="font-size:22px;font-weight:bold;margin-bottom:8px;">
    Latest Updates:
  </div>
  <div style="margin-bottom:28px;"></div>

{{ 
(() => {

  let index = 0;
  let expectTitle = true;   // allow first title immediately
  let currentLabel = null;

  return $node["Execute Command1"].json["stdout"]
    .split('\n')
    .map(line => {
      let t = line.trim();
      if (!t) return '';

      /* ======================
         DIVIDER
      ====================== */
      if (/^[-=]{3,}$/.test(t)) {
        expectTitle = true;
        currentLabel = null;
        return `<div style="border-top:2px solid #000;margin:28px 0;"></div>`;
      }

      /* ======================
         HARD BLOCK: LINK (never a title)
      ====================== */
      if (t.match(/^\d+\.\s*Link:/) || t.startsWith('Link:')) {
        currentLabel = null;
        expectTitle = true;

        const clean = t.replace(/^\d+\.\s*/, '');
        const url = clean.replace('Link:', '').trim();

        return `
          <div style="margin-top:6px;">
            <span style="font-weight:bold;">Link:</span>
            <a href="${url}" style="color:#1155cc;text-decoration:none;margin-left:4px;">
              ${url}
            </a>
          </div>
        `;
      }

      /* ======================
         TITLE
      ====================== */
      if (
        expectTitle &&
        !currentLabel &&
        !t.endsWith(':') &&
        !t.startsWith('Link:')
      ) {
        index++;
        expectTitle = false;
        return `
          <div style="font-size:17px;font-weight:bold;margin:16px 0 10px;">
            ${index}. ${t}
          </div>
        `;
      }

      /* ======================
         SECTION LABELS
      ====================== */
      if (t === 'What happened:' || t === 'Who should care:') {
        currentLabel = t;
        return `
          <div style="font-weight:bold;margin-top:12px;">
            ${t}
          </div>
        `;
      }

      /* ======================
         SOURCE (bold label, normal value)
      ====================== */
      if (t.startsWith('Source:')) {
        currentLabel = null;
        return `
          <div style="margin-top:8px;">
            <span style="font-weight:bold;">Source:</span>
            <span style="font-weight:normal;"> ${t.replace('Source:', '').trim()}</span>
          </div>
        `;
      }

      /* ======================
         LABEL DESCRIPTION (normal text)
      ====================== */
      if (currentLabel) {
        return `
          <div style="margin-top:4px;font-weight:normal;">
            ${t}
          </div>
        `;
      }

      /* ======================
         FALLBACK
      ====================== */
      return `
        <div style="margin-top:6px;">
          ${t}
        </div>
      `;

    }).join('');

})()
}}

</div>
